function Admin({onError}:{onError:(s:string)=>void}){const [root,setRoot]=useState('');const [token,setToken]=useState(sessionStorage.getItem('coukong-admin')||'');const [error,setError]=useState('');async function endSession(){try{await clearAdminCreationPending(token)}catch{onError('管理会话已失效，但本机待生成资料清理失败，请关闭此标签页。')}if(sessionStorage.getItem('coukong-admin')===token){sessionStorage.removeItem('coukong-admin');setToken('')}}return <>{!token?<><h1 className="page-title">活动管理</h1><section className="card online-section"><label>管理员密码<input className="input" type="password" value={root} onChange={e=>setRoot(e.target.value)} autoComplete="off"/></label><button className="btn btn-primary" onClick={async()=>{try{const sessionToken=newToken();await api('/admin/session',undefined,{rootToken:root,sessionToken});sessionStorage.setItem('coukong-admin',sessionToken);setToken(sessionToken);setRoot('');setError('')}catch(e){setError((e as Error).message)}}}>进入管理</button>{error&&<p className="notice" role="alert">{error}</p>}</section></>:<><AdminActivity headerActions={<button className="btn btn-surface" onClick={async()=>{try{await api('/admin/session',token,undefined,'DELETE');await endSession()}catch(e){if(e instanceof ApiFailure&&e.status===401){await endSession();onError('管理会话已过期，请重新进入')}else onError('未能退出管理会话，请重试。'+(e as Error).message)}}}>退出登录</button>} token={token} renderMaps={props=><MapEditor {...props}/>} onError={onError} onExpired={()=>{void endSession();onError('管理会话已过期，请重新进入')}}/></>}</>}
